'use client'

import { cn, useSignal, useSignalEffect, useSignals } from '@cascivo/core'
import { builtin, t } from '@cascivo/i18n'
import { useRef } from 'react'
import type { CSSProperties, ReactNode } from 'react'
import { Spinner } from '../spinner/spinner'
import styles from './pull-to-refresh.module.css'

/** Finger travel is damped by this factor so the pull feels rubber-banded. */
const RESISTANCE = 0.5

export interface PullToRefreshProps {
  /** Invoked when the pull passes the threshold; the spinner shows until it settles. */
  onRefresh: () => Promise<unknown> | unknown
  children: ReactNode
  /**
   * Pull distance (px) required to trigger a refresh.
   *
   * @defaultValue `64`
   * @see the component manifest
   */
  threshold?: number
  /**
   * When true, disables the control and removes it from the tab order.
   *
   * @defaultValue `false`
   * @see the component manifest
   */
  disabled?: boolean
  labels?: { pull?: string; release?: string; refreshing?: string }
  className?: string
}

/**
 * Wraps a vertically scrollable region and triggers `onRefresh` when the user pulls
 * down past a threshold while scrolled to the top. The gesture is damped (rubber-band),
 * shows a spinner while the returned promise settles, then springs back. Pointer logic
 * runs in `useSignalEffect`; CSS translate only, no animation library. Pull is only armed
 * at scrollTop 0, so normal scrolling is untouched.
 */
export function PullToRefresh({
  onRefresh,
  children,
  threshold = 64,
  disabled = false,
  labels,
  className,
}: PullToRefreshProps) {
  useSignals()
  const viewportRef = useRef<HTMLDivElement>(null)
  const pull = useSignal(0)
  const refreshing = useSignal(false)
  const dragging = useSignal(false)

  const onRefreshRef = useRef(onRefresh)
  onRefreshRef.current = onRefresh
  const thresholdRef = useRef(threshold)
  thresholdRef.current = threshold
  const disabledRef = useRef(disabled)
  disabledRef.current = disabled

  useSignalEffect(() => {
    const el = viewportRef.current
    if (!el || typeof window === 'undefined') return

    let startY = 0
    let active = false

    const onDown = (event: PointerEvent): void => {
      if (disabledRef.current || refreshing.value || el.scrollTop > 0) return
      startY = event.clientY
      active = true
    }
    const onMove = (event: PointerEvent): void => {
      if (!active || refreshing.value) return
      const dy = event.clientY - startY
      // Cancel if the user scrolls up, or the list isn't at the top anymore.
      if (dy <= 0 || el.scrollTop > 0) {
        pull.value = 0
        dragging.value = false
        return
      }
      // Suppress native overscroll while we own the gesture.
      event.preventDefault()
      dragging.value = true
      pull.value = Math.min(dy * RESISTANCE, thresholdRef.current * 1.5)
    }
    const onUp = (): void => {
      if (!active) return
      active = false
      dragging.value = false
      if (refreshing.value) return
      if (pull.value >= thresholdRef.current) {
        refreshing.value = true
        pull.value = thresholdRef.current
        Promise.resolve(onRefreshRef.current()).then(
          () => {
            refreshing.value = false
            pull.value = 0
          },
          () => {
            refreshing.value = false
            pull.value = 0
          },
        )
      } else {
        pull.value = 0
      }
    }

    el.addEventListener('pointerdown', onDown)
    window.addEventListener('pointermove', onMove, { passive: false })
    window.addEventListener('pointerup', onUp)
    window.addEventListener('pointercancel', onUp)
    return () => {
      el.removeEventListener('pointerdown', onDown)
      window.removeEventListener('pointermove', onMove)
      window.removeEventListener('pointerup', onUp)
      window.removeEventListener('pointercancel', onUp)
    }
  })

  const distance = refreshing.value ? threshold : pull.value
  const progress = Math.min(distance / threshold, 1)
  const ready = progress >= 1

  const status = refreshing.value
    ? (labels?.refreshing ?? t(builtin.pullToRefresh.refreshing))
    : ready
      ? (labels?.release ?? t(builtin.pullToRefresh.release))
      : distance > 0
        ? (labels?.pull ?? t(builtin.pullToRefresh.pull))
        : ''

  const rootStyle = { '--_pull': `${distance}px` } as CSSProperties

  return (
    <div className={cn(styles['root'], className)} style={rootStyle}>
      <div className={styles['indicator']} data-dragging={dragging.value ? '' : undefined}>
        {refreshing.value ? (
          <Spinner size="sm" />
        ) : (
          <svg
            aria-hidden="true"
            viewBox="0 0 16 16"
            className={styles['arrow']}
            data-ready={ready ? '' : undefined}
            style={{ opacity: progress }}
          >
            <path
              d="M8 13V3M4 7l4-4 4 4"
              fill="none"
              stroke="currentColor"
              strokeWidth="1.5"
              strokeLinecap="round"
              strokeLinejoin="round"
            />
          </svg>
        )}
      </div>
      <span role="status" aria-live="polite" className={styles['srOnly']}>
        {status}
      </span>
      <div
        ref={viewportRef}
        className={styles['viewport']}
        data-dragging={dragging.value ? '' : undefined}
      >
        {children}
      </div>
    </div>
  )
}

@layer cascivo.component {
  .root {
    position: relative;
    overflow: hidden;
    block-size: 100%;
  }

  .indicator {
    position: absolute;
    inset-inline: 0;
    inset-block-start: 0;
    display: flex;
    align-items: center;
    justify-content: center;
    block-size: var(--_pull, 0px);
    overflow: hidden;
    color: var(--cascivo-color-text-muted);
    transition: block-size var(--cascivo-motion-enter);

    &[data-dragging] {
      transition: none;
    }
  }

  .arrow {
    inline-size: 1.25rem;
    block-size: 1.25rem;
    transition: rotate var(--cascivo-motion-enter);

    &[data-ready] {
      rotate: 180deg;
    }
  }

  .viewport {
    block-size: 100%;
    overflow-y: auto;
    overscroll-behavior: contain;
    transform: translateY(var(--_pull, 0px));
    transition: transform var(--cascivo-motion-enter);

    &[data-dragging] {
      transition: none;
    }
  }

  .srOnly {
    position: absolute;
    inline-size: 1px;
    block-size: 1px;
    margin: -1px;
    padding: 0;
    border: 0;
    overflow: hidden;
    clip-path: inset(50%);
    white-space: nowrap;
  }

  @media (prefers-reduced-motion: reduce) {
    .indicator,
    .arrow,
    .viewport {
      transition: none;
    }
  }
}

import type { ComponentMeta } from '@cascivo/core'

export const meta: ComponentMeta = {
  name: 'PullToRefresh',
  description:
    'Wraps a scrollable region and triggers a refresh when pulled down past a threshold at the top',
  category: 'feedback',
  // A pointer gesture is the entire trigger.
  clientJs: 'required',
  states: ['idle', 'pulling', 'ready', 'refreshing'],
  variants: [],
  sizes: [],
  props: [
    {
      name: 'onRefresh',
      type: '() => Promise<unknown> | unknown',
      required: true,
      description: 'Called when the pull passes the threshold; the spinner shows until it settles',
    },
    {
      name: 'children',
      description: 'Content rendered inside the component.',
      type: 'React.ReactNode',
      required: true,
    },
    {
      name: 'threshold',
      description: 'Pull distance (px) required to trigger a refresh.',
      type: 'number',
      required: false,
      default: '64',
    },
    {
      name: 'disabled',
      default: 'false',
      description: 'When true, disables the control and removes it from the tab order.',
      type: 'boolean',
      required: false,
    },
    {
      name: 'labels',
      description: 'Overrides for the component’s user-visible strings (i18n).',
      type: '{ pull?: string; release?: string; refreshing?: string }',
      required: false,
    },
    {
      name: 'className',
      description: 'Additional CSS class names merged onto the root element.',
      type: 'string',
      required: false,
    },
  ],
  tokens: ['--cascivo-color-text-muted', '--cascivo-motion-enter'],
  accessibility: {
    role: 'status',
    wcag: '2.2-AA',
    keyboard: [],
  },
  examples: [
    {
      title: 'Basic',
      code: `<PullToRefresh onRefresh={() => refetch()}>
  <FeedList items={items} />
</PullToRefresh>`,
      description: 'The spinner shows until the returned promise settles.',
    },
    {
      title: 'Custom threshold',
      code: `<PullToRefresh onRefresh={loadLatest} threshold={96}>
  <MessageList />
</PullToRefresh>`,
      description: 'Requires a longer pull before a refresh is triggered.',
    },
  ],
  dependencies: ['@cascivo/core', '@cascivo/i18n'],
  registryDependencies: ['spinner'],
  tags: ['feedback', 'pull-to-refresh', 'mobile', 'gesture', 'scroll', 'refresh'],
  intent: {
    whenToUse: [
      'A scrollable list or feed on touch devices that the user refreshes by pulling down from the top',
      'Mobile screens where a dedicated refresh button would be redundant or out of reach',
      'Content that updates on demand and benefits from a familiar pull gesture',
    ],
    whenNotToUse: [
      'Desktop, pointer-first surfaces — provide an explicit Refresh button',
      'Content that auto-refreshes or paginates on scroll — use infinite scroll instead',
      'Regions that are not the primary scroll container of the screen',
    ],
    antiPatterns: [
      {
        bad: 'Wrapping a non-scrolling element and relying on pull as the only refresh path',
        good: 'Wrap the scroll container and also expose a Refresh control for non-touch users',
        why: 'Pull-to-refresh is touch-only; keyboard and pointer users need an explicit control',
      },
    ],
    related: [
      {
        name: 'Spinner',
        relationship: 'contains',
        reason: 'Shows the Spinner while the refresh promise settles',
      },
      {
        name: 'ScrollArea',
        relationship: 'pairs-with',
        reason: 'Wraps a scrollable region; pair with the app’s scroll container',
      },
    ],
    a11yRationale:
      'The gesture is a touch-only enhancement: it arms only at scrollTop 0 and uses touch-action/overscroll containment so normal scrolling and keyboard use are unaffected. A polite aria-live status region announces the pull, release, and refreshing states (strings from the i18n catalog), and the Spinner exposes role="status" while loading. Because pull-to-refresh cannot be performed without a pointer, apps should also offer an explicit refresh control for keyboard users.',
    flexibility: [
      {
        area: 'threshold',
        level: 'flexible',
        note: 'Pull distance required to trigger is configurable (default 64px)',
      },
      {
        area: 'onRefresh',
        level: 'flexible',
        note: 'May return a promise; the spinner persists until it settles',
      },
    ],
  },
}
